321	    /**
322	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
323	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
324	     * does not catch). The names of all offending fields are collected so the caller receives a
325	     * 400 response whose {@code errors} array lists each one.
326	     */
327	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
328	        List<String> missingFields = new ArrayList<>();
329	        if (isBlank(ownerFieldsDto.getFirstName())) {
330	            missingFields.add("firstName");
331	        }
332	        if (isBlank(ownerFieldsDto.getLastName())) {
333	            missingFields.add("lastName");
334	        }
335	        if (isBlank(ownerFieldsDto.getAddress())) {
336	            missingFields.add("address");
337	        }
338	        if (isBlank(ownerFieldsDto.getCity())) {
339	            missingFields.add("city");
340	        }
341	        if (isBlank(ownerFieldsDto.getTelephone())) {
342	            missingFields.add("telephone");
343	        }
344	        if (!missingFields.isEmpty()) {
345	            throw new InvalidOwnerFieldsException(missingFields);
346	        }
347	    }
