349	    private static boolean isBlank(String value) {
350	        return value == null || value.trim().isEmpty();
351	    }
352	
353	    /**
354	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
355	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
356	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
357	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
358	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
359	     * means an address that is blank after normalization is rejected like a missing one.
360	     */
361	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
362	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
363	    }
364	
365	    /**
366	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
367	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
368	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
369	     * address is returned unchanged, making it safe to apply to stored values during comparison.
370	     */
371	    private static String canonicalAddress(String address) {
372	        if (address == null) {
373	            return null;
374	        }
375	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
376	        if (collapsed.isEmpty()) {
377	            return "";
378	        }
379	        String[] tokens = collapsed.split(" ");
380	        StringBuilder sb = new StringBuilder(collapsed.length());
381	        for (int i = 0; i < tokens.length; i++) {
382	            if (i > 0) {
383	                sb.append(' ');
384	            }
385	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
386	        }
387	        return sb.toString();
388	    }
