390	    /**
391	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
392	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
393	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
394	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
395	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
396	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
397	     * written back onto the request so it is what gets stored and returned. Any value that cannot
398	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
399	     * {@code telephone}.
400	     */
401	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
402	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
403	    }
404	
405	    /**
406	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
407	     * (400) naming {@code telephone} when it cannot form a valid number.
408	     */
409	    private static String toE164(String telephone) {
410	        if (telephone == null) {
411	            throw new InvalidOwnerFieldsException(List.of("telephone"));
412	        }
413	        boolean hasCountryCode = telephone.trim().startsWith("+");
414	        String digits = telephone.replaceAll("\\D", "");
415	        String countryCode;
416	        String national;
417	        if (hasCountryCode) {
418	            countryCode = matchCountryCode(digits);
419	            national = digits;
420	        } else {
421	            countryCode = "61";
422	            if (digits.startsWith("0")) {
423	                digits = digits.substring(1);
424	            }
425	            national = "61" + digits;
426	        }
427	        if (!national.matches("[0-9]{8,15}")) {
428	            throw new InvalidOwnerFieldsException(List.of("telephone"));
429	        }
430	        if (countryCode != null) {
431	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
432	            if (requiredLength != null
433	                && national.length() - countryCode.length() != requiredLength) {
434	                throw new InvalidOwnerFieldsException(List.of("telephone"));
435	            }
436	        }
437	        return "+" + national;
438	    }
439	
440	    /**
441	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
442	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
443	     * the number is not length-checked against a country.
444	     */
445	    private static String matchCountryCode(String digits) {
446	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
447	            .filter(digits::startsWith)
448	            .max(Comparator.comparingInt(String::length))
449	            .orElse(null);
450	    }
451	
452	    /**
453	     * Rejects creating an owner that duplicates an existing one, either as a household duplicate or
454	     * as an exact identity duplicate. The household is now keyed on the computed {@code householdId}
455	     * (a deterministic function of the normalized last name and postcode, see
456	     * {@link #computeHouseholdId}), so any existing owner already carrying the same {@code householdId}
457	     * belongs to the same household and makes the new owner a household duplicate. Independently, an
458	     * exact match on the derived {@code identityKey} - {@code normalizedTelephone + '|' + (email or
459	     * empty) + '|' + (householdId or empty)} - is also a duplicate; this still catches owners with no
460	     * postcode (and therefore no household) that share a telephone and email. Both checks are a 409.
461	     *
462	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block: a request that opts in
463	     * is allowed through even when it lands in an existing household, so it is created as a declared
464	     * household member rather than rejected. The incoming telephone and email have already been
465	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}; each existing owner's key
466	     * is derived the same way before comparison. A match results in a 409 response naming
467	     * {@code identityKey}.
468	     */
469	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
470	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
471	            return;
472	        }
473	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
474	        for (Owner existing : this.clinicService.findAllOwners()) {
475	            boolean householdDuplicate = householdId != null && householdId.equals(existing.getHouseholdId());
476	            if (householdDuplicate || identityKey.equals(existingIdentityKey(existing))) {
477	                throw new DuplicateOwnerIdentityException(identityKey);
478	            }
479	        }
480	    }
481	
482	    /**
483	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
484	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
485	     * are expected to already be in their normalized (E.164, lower-cased) forms.
486	     */
487	    private static String identityKey(String telephone, String email, String householdId) {
488	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
489	    }
490	
491	    /**
492	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
493	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
494	     * the stored email is lower-cased, and the stored household id is used as-is.
495	     */
496	    private static String existingIdentityKey(Owner existing) {
497	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
498	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
499	        return identityKey(telephone, email, existing.getHouseholdId());
500	    }
501	
502	    private static String orEmpty(String value) {
503	        return value == null ? "" : value;
504	    }
505	
506	    /**
507	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
508	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
509	     */
510	    private static String normalizeExisting(String telephone) {
511	        try {
512	            return toE164(telephone);
513	        } catch (InvalidOwnerFieldsException ex) {
514	            return null;
515	        }
516	    }
517	
518	    /**
519	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
520	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
521	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
522	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
523	     */
524	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
525	        String city = ownerFieldsDto.getCity();
526	        int count = 0;
527	        for (Owner existing : this.clinicService.findAllOwners()) {
528	            if (city.equalsIgnoreCase(existing.getCity())) {
529	                count++;
530	            }
531	        }
532	        if (count >= MAX_OWNERS_PER_CITY) {
533	            throw new OwnerCityAtCapacityException(city);
534	        }
535	    }
536	
537	    /**
538	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
539	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
540	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
541	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
542	     */
543	    private void rejectDailyLimitReached(LocalDate registrationDate) {
544	        int count = 0;
545	        for (Owner existing : this.clinicService.findAllOwners()) {
546	            if (registrationDate.equals(existing.getRegistrationDate())) {
547	                count++;
548	            }
549	        }
550	        if (count >= MAX_OWNERS_PER_DAY) {
551	            throw new DailyOwnerLimitReachedException(registrationDate);
552	        }
553	    }
554	
555	    /**
556	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
557	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
558	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
559	     */
560	    private static String normalizeForComparison(String value) {
561	        if (value == null) {
562	            return "";
563	        }
564	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
565	    }
566	
567	    /**
568	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
569	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
570	     * written back onto the request so that is what gets stored and returned. A present but invalid
571	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
572	     */
573	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
574	        String email = ownerFieldsDto.getEmail();
575	        if (email == null) {
576	            return;
577	        }
578	        String trimmed = email.trim();
579	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
580	            throw new InvalidOwnerFieldsException(List.of("email"));
581	        }
582	        String normalized = trimmed.toLowerCase(Locale.ROOT);
583	        String domain = normalized.substring(normalized.indexOf('@') + 1);
584	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
585	            throw new InvalidOwnerFieldsException(List.of("email"));
586	        }
587	        ownerFieldsDto.setEmail(normalized);
588	    }
589	
590	    /**
591	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
592	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
593	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
594	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
595	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
596	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
597	     * as-is so it is stored and returned.
598	     */
599	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
600	        String postcode = ownerFieldsDto.getPostcode();
601	        if (postcode == null) {
602	            return;
603	        }
604	        if (!postcode.matches("[0-9]{4}")) {
605	            throw new InvalidOwnerFieldsException(List.of("postcode"));
606	        }
607	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
608	        if (range != null) {
609	            int value = Integer.parseInt(postcode);
610	            if (value < range[0] || value > range[1]) {
611	                throw new InvalidOwnerFieldsException(List.of("postcode"));
612	            }
613	        }
614	    }
615	
616	    /**
617	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
618	     * day. When the caller supplies no value it defaults to the server's current date; a value
619	     * provided in the request is kept. A supplied value later than the server's current date is
620	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
621	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
622	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
623	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
624	     * every value derived from the registration date is based on.
625	     */
626	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
627	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
628	        if (effective == null) {
629	            effective = LocalDate.now();
630	        }
631	        else if (effective.isAfter(LocalDate.now())) {
632	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
633	        }
634	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
635	    }
636	
637	    /**
638	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
639	     * Monday; a weekday is returned unchanged.
640	     */
641	    private static LocalDate toBusinessDay(LocalDate date) {
642	        return switch (date.getDayOfWeek()) {
643	            case SATURDAY -> date.plusDays(2);
644	            case SUNDAY -> date.plusDays(1);
645	            default -> date;
646	        };
647	    }
648	
649	    /**
650	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
651	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
652	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
653	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
654	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
655	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
656	     * pure function of region, telephone and last name.
657	     */
658	    private void assignCustomerCode(Owner owner) {
659	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
660	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
661	        owner.setCustomerCode(deduplicateCustomerCode(region + "-" + hash8));
662	    }
663	
664	    /**
665	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
666	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
667	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
668	     * among them.
669	     */
670	    private String deduplicateCustomerCode(String customerCode) {
671	        Set<String> existing = new HashSet<>();
672	        for (Owner owner : this.clinicService.findAllOwners()) {
673	            if (owner.getCustomerCode() != null) {
674	                existing.add(owner.getCustomerCode());
675	            }
676	        }
677	        if (!existing.contains(customerCode)) {
678	            return customerCode;
679	        }
680	        int n = 2;
681	        while (existing.contains(customerCode + "-" + n)) {
682	            n++;
683	        }
684	        return customerCode + "-" + n;
685	    }
686	
687	    /**
688	     * Assigns the owner's {@code membershipNumber} on create, formatted
689	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
690	     * {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Assigned after
691	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
692	     * inputs are present.
693	     */
694	    private void assignMembershipNumber(Owner owner) {
695	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
696	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
697	    }
698	
699	    /**
700	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
701	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
702	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
703	     */
704	    private void assignNamesakeCount(Owner owner) {
705	        String firstName = owner.getFirstName();
706	        String lastName = owner.getLastName();
707	        int count = 0;
708	        for (Owner existing : this.clinicService.findAllOwners()) {
709	            if (firstName.equalsIgnoreCase(existing.getFirstName())
710	                && lastName.equalsIgnoreCase(existing.getLastName())) {
711	                count++;
712	            }
713	        }
714	        owner.setNamesakeCount(count);
715	    }
716	
717	    /**
718	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
719	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
720	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
721	     * {@value #TENURE_LEVEL_THRESHOLD_DAYS} days. The points are then mapped to a level of 1 (0-1
722	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
723	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
724	     * tenure, so the tenure bonus never applies on create.
725	     */
726	    private void assignMembership(Owner owner) {
727	        int points = 0;
728	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
729	            points += 2;
730	        }
731	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
732	            points += 1;
733	        }
734	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
735	            points += 2;
736	        }
737	        if (tenureDays(owner) > TENURE_LEVEL_THRESHOLD_DAYS) {
738	            points += 3;
739	        }
740	        owner.setMembershipPoints(points);
741	        owner.setMembershipLevel(membershipLevelForPoints(points));
742	    }
743	
744	    /**
745	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
746	     * 4-5, and 4 for 6 or more points.
747	     */
748	    private int membershipLevelForPoints(int points) {
749	        if (points <= 1) {
750	            return 1;
751	        }
752	        if (points <= 3) {
753	            return 2;
754	        }
755	        if (points <= 5) {
756	            return 3;
757	        }
758	        return 4;
759	    }
760	
761	    /**
762	     * The tenure, in days, of a newly created owner. Tenure accrues from membership over time, and a
763	     * new owner has not been a member for any elapsed time yet, so this is always {@code 0} on create
764	     * (regardless of any backdated {@code registrationDate}).
765	     */
766	    private long tenureDays(Owner owner) {
767	        return 0L;
768	    }
769	
770	    /**
771	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
772	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
773	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
774	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
775	     * pre-existing owners for that day.
776	     */
777	    private void assignBulkSignupWarning(Owner owner) {
778	        LocalDate registrationDate = owner.getRegistrationDate();
779	        int count = 0;
780	        for (Owner existing : this.clinicService.findAllOwners()) {
781	            if (registrationDate.equals(existing.getRegistrationDate())) {
782	                count++;
783	            }
784	        }
785	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
786	    }
787	
788	    /**
789	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
790	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
791	     * possible duplicate when an existing owner shares its {@code lastName} (compared
792	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
793	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
794	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
795	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
796	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
797	     *
798	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
799	     * has deliberately opted into an existing household, so its shared last name and postcode are
800	     * expected rather than a suspected duplicate.
801	     */
802	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
803	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
804	            owner.setPossibleDuplicate(false);
805	            owner.setPossibleDuplicateOf(null);
806	            return;
807	        }
808	        String lastName = owner.getLastName();
809	        String postcode = owner.getPostcode();
810	        String telephone = owner.getTelephone();
811	        Integer matchId = null;
812	        if (postcode != null) {
813	            for (Owner existing : this.clinicService.findAllOwners()) {
814	                if (lastName.equalsIgnoreCase(existing.getLastName())
815	                    && postcode.equals(existing.getPostcode())
816	                    && !postcode.isBlank()
817	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
818	                    && existing.getId() != null
819	                    && (matchId == null || existing.getId() < matchId)) {
820	                    matchId = existing.getId();
821	                }
822	            }
823	        }
824	        owner.setPossibleDuplicate(matchId != null);
825	        owner.setPossibleDuplicateOf(matchId);
826	    }
827	
828	    /**
829	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
830	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
831	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
832	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
833	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
834	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
835	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
836	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
837	     * ({@link #assignHouseholdMembership}).
838	     */
839	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
840	        String postcode = ownerFieldsDto.getPostcode();
841	        if (postcode == null || postcode.isBlank()) {
842	            return null;
843	        }
844	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
845	        return shaHexUpper(lastName + "|" + postcode, 12);
846	    }
847	
848	    /**
849	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
850	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
851	     * every existing owner already carrying the same identifier. Runs after the owner's
852	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
853	     * Left {@code null} when the owner belongs to no household.
854	     */
855	    private void assignHouseholdMembership(Owner owner) {
856	        String householdId = owner.getHouseholdId();
857	        if (householdId == null || householdId.isBlank()) {
858	            owner.setHouseholdMemberCount(null);
859	            return;
860	        }
861	        int count = 1;
862	        for (Owner existing : this.clinicService.findAllOwners()) {
863	            if (householdId.equals(existing.getHouseholdId())) {
864	                count++;
865	            }
866	        }
867	        owner.setHouseholdMemberCount(count);
868	    }
869	
870	    /**
871	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
872	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
873	     * identifier, both stable functions of their inputs.
874	     */
875	    private static String shaHexUpper(String input, int length) {
876	        try {
877	            byte[] digest = MessageDigest.getInstance("SHA-256")
878	                .digest(input.getBytes(StandardCharsets.UTF_8));
879	            StringBuilder hex = new StringBuilder(digest.length * 2);
880	            for (byte b : digest) {
881	                hex.append(String.format("%02x", b));
882	            }
883	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
884	        } catch (NoSuchAlgorithmException ex) {
885	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
886	        }
887	    }
888	}
